import { z } from 'zod'
import { OrderId, OrderStatus } from './schemas.ts'

/** GET /orders query string, after the router has turned it into an object of strings. */
export const ListOrdersQuery = z.object({
  // prefault parses the default, so it goes through the split/pipe like a real query value.
  status: z
    .string()
    .transform((value) => value.split(','))
    .pipe(z.array(OrderStatus))
    .prefault('pending,paid'),
  limit: z.coerce.number().int().min(1).max(100).default(20),
  includeArchived: z.coerce.boolean().default(false),
  cursor: OrderId.optional(),
})
export type ListOrdersQuery = z.infer<typeof ListOrdersQuery>
EOF
cat > src/pricing.ts <<'EOF'
import { z } from 'zod'
import { Money, Order } from './schemas.ts'

/** Order total in minor units. Validates its input and output, so callers can pass raw JSON. */
export const orderTotal = z
  .function({ input: [Order], output: Money })
  .implement((order) => {
    const currency = order.items[0].unitPrice.currency
    let amount = 0
    for (const item of order.items) {
      if (item.unitPrice.currency !== currency) throw new Error('Mixed currencies in one order')
      amount += item.unitPrice.amount * item.quantity
    }
    return { amount, currency }
  })
EOF
